for i in range(10):
    if i == 4:
        break
    print(i)
# prints 0, 1, 2, 3 — then stops

for i in range(5):
    if i == 2:
        continue
    print(i)
# prints 0, 1, 3, 4 — skips only 2

for row in range(2):
    for col in range(3):
        print(row, col)

numbers = [3, -1, 5, 0, 8]

for n in numbers:
    if n == 0:
        break          # stop entirely once we hit zero
    if n < 0:
        continue        # skip negatives, keep going
    print(n)

# Output:
# 3
# 5

